INSERT INTO "comments" ("id", "issue_id", "parent_id", "author_id", "anon_id", "content", "created_at") VALUES ('c0000000-0000-4000-8000-000000000001', 1, NULL, 4, 'anon_704b942dbced6982', 'This pothole has been there for weeks and it keeps getting deeper. A scooter skid here yesterday.', '2026-08-10 09:00:00.000000') ON CONFLICT ("id") DO UPDATE SET "issue_id" = excluded."issue_id", "parent_id" = excluded."parent_id", "author_id" = excluded."author_id", "anon_id" = excluded."anon_id", "content" = excluded."content", "created_at" = excluded."created_at";
INSERT INTO "comments" ("id", "issue_id", "parent_id", "author_id", "anon_id", "content", "created_at") VALUES ('c0000000-0000-4000-8000-000000000002', 1, 'c0000000-0000-4000-8000-000000000001', 3, 'anon_a8891fdf13388dec', 'Yes, and it is worst in the evening when cars cannot see it. Hoping the ward councilor sees this soon.', '2026-08-10 09:20:00.000000') ON CONFLICT ("id") DO UPDATE SET "issue_id" = excluded."issue_id", "parent_id" = excluded."parent_id", "author_id" = excluded."author_id", "anon_id" = excluded."anon_id", "content" = excluded."content", "created_at" = excluded."created_at";
INSERT INTO "comments" ("id", "issue_id", "parent_id", "author_id", "anon_id", "content", "created_at") VALUES ('c0000000-0000-4000-8000-000000000003', 1, 'c0000000-0000-4000-8000-000000000002', 5, 'anon_2d46379e858dd668', 'I called the helpline too. Let us keep this report visible until it is fixed.', '2026-08-10 09:35:00.000000') ON CONFLICT ("id") DO UPDATE SET "issue_id" = excluded."issue_id", "parent_id" = excluded."parent_id", "author_id" = excluded."author_id", "anon_id" = excluded."anon_id", "content" = excluded."content", "created_at" = excluded."created_at";
INSERT INTO "comments" ("id", "issue_id", "parent_id", "author_id", "anon_id", "content", "created_at") VALUES ('c0000000-0000-4000-8000-000000000004', 1, NULL, 6, 'anon_b4527b59275b7cf1', 'Adding my upvote. This stretch really needs resurfacing.', '2026-08-10 10:00:00.000000') ON CONFLICT ("id") DO UPDATE SET "issue_id" = excluded."issue_id", "parent_id" = excluded."parent_id", "author_id" = excluded."author_id", "anon_id" = excluded."anon_id", "content" = excluded."content", "created_at" = excluded."created_at";
INSERT INTO "comments" ("id", "issue_id", "parent_id", "author_id", "anon_id", "content", "created_at") VALUES ('c0000000-0000-4000-8000-000000000005', 2, NULL, 3, 'anon_a8891fdf13388dec', 'The drain on the temple side is completely choked with plastic bottles.', '2026-08-09 07:00:00.000000') ON CONFLICT ("id") DO UPDATE SET "issue_id" = excluded."issue_id", "parent_id" = excluded."parent_id", "author_id" = excluded."author_id", "anon_id" = excluded."anon_id", "content" = excluded."content", "created_at" = excluded."created_at";
INSERT INTO "comments" ("id", "issue_id", "parent_id", "author_id", "anon_id", "content", "created_at") VALUES ('c0000000-0000-4000-8000-000000000006', 2, 'c0000000-0000-4000-8000-000000000005', 4, 'anon_704b942dbced6982', 'Exactly. Cleaning just this one drain would clear the whole stretch.', '2026-08-09 07:30:00.000000') ON CONFLICT ("id") DO UPDATE SET "issue_id" = excluded."issue_id", "parent_id" = excluded."parent_id", "author_id" = excluded."author_id", "anon_id" = excluded."anon_id", "content" = excluded."content", "created_at" = excluded."created_at";
INSERT INTO "comments" ("id", "issue_id", "parent_id", "author_id", "anon_id", "content", "created_at") VALUES ('c0000000-0000-4000-8000-000000000007', 3, NULL, 6, 'anon_b4527b59275b7cf1', 'Please be careful near the market entrance, the wire sags right over the paan shop.', '2026-08-08 10:00:00.000000') ON CONFLICT ("id") DO UPDATE SET "issue_id" = excluded."issue_id", "parent_id" = excluded."parent_id", "author_id" = excluded."author_id", "anon_id" = excluded."anon_id", "content" = excluded."content", "created_at" = excluded."created_at";
INSERT INTO "comments" ("id", "issue_id", "parent_id", "author_id", "anon_id", "content", "created_at") VALUES ('c0000000-0000-4000-8000-000000000008', 3, NULL, 9, 'anon_98198bc61ba345c8', 'I reported the same last month. Glad it is finally under review.', '2026-08-09 11:00:00.000000') ON CONFLICT ("id") DO UPDATE SET "issue_id" = excluded."issue_id", "parent_id" = excluded."parent_id", "author_id" = excluded."author_id", "anon_id" = excluded."anon_id", "content" = excluded."content", "created_at" = excluded."created_at";
INSERT INTO "comments" ("id", "issue_id", "parent_id", "author_id", "anon_id", "content", "created_at") VALUES ('c0000000-0000-4000-8000-000000000009', 6, NULL, 10, 'anon_d300079cfe4046d6', 'The crew did come and jet the drain, water is going down now.', '2026-08-08 09:00:00.000000') ON CONFLICT ("id") DO UPDATE SET "issue_id" = excluded."issue_id", "parent_id" = excluded."parent_id", "author_id" = excluded."author_id", "anon_id" = excluded."anon_id", "content" = excluded."content", "created_at" = excluded."created_at";
INSERT INTO "comments" ("id", "issue_id", "parent_id", "author_id", "anon_id", "content", "created_at") VALUES ('c0000000-0000-4000-8000-000000000010', 6, 'c0000000-0000-4000-8000-000000000009', 4, 'anon_704b942dbced6982', 'Thanks for confirming. If a couple more neighbours confirm, this can be marked resolved.', '2026-08-08 09:30:00.000000') ON CONFLICT ("id") DO UPDATE SET "issue_id" = excluded."issue_id", "parent_id" = excluded."parent_id", "author_id" = excluded."author_id", "anon_id" = excluded."anon_id", "content" = excluded."content", "created_at" = excluded."created_at";
INSERT INTO "comments" ("id", "issue_id", "parent_id", "author_id", "anon_id", "content", "created_at") VALUES ('c0000000-0000-4000-8000-000000000011', 7, NULL, 6, 'anon_b4527b59275b7cf1', 'The leak has stopped and the road is patched up. Looks good now.', '2026-07-19 08:00:00.000000') ON CONFLICT ("id") DO UPDATE SET "issue_id" = excluded."issue_id", "parent_id" = excluded."parent_id", "author_id" = excluded."author_id", "anon_id" = excluded."anon_id", "content" = excluded."content", "created_at" = excluded."created_at";
INSERT INTO "comments" ("id", "issue_id", "parent_id", "author_id", "anon_id", "content", "created_at") VALUES ('c0000000-0000-4000-8000-000000000012', 7, 'c0000000-0000-4000-8000-000000000011', 9, 'anon_98198bc61ba345c8', 'Confirmed from my side as well. No more water on the crossing.', '2026-07-19 09:00:00.000000') ON CONFLICT ("id") DO UPDATE SET "issue_id" = excluded."issue_id", "parent_id" = excluded."parent_id", "author_id" = excluded."author_id", "anon_id" = excluded."anon_id", "content" = excluded."content", "created_at" = excluded."created_at";
INSERT INTO "comments" ("id", "issue_id", "parent_id", "author_id", "anon_id", "content", "created_at") VALUES ('c0000000-0000-4000-8000-000000000013', 7, NULL, 10, 'anon_d300079cfe4046d6', 'Fixed, water wastage has stopped. Thanks everyone for the quick action.', '2026-07-20 08:30:00.000000') ON CONFLICT ("id") DO UPDATE SET "issue_id" = excluded."issue_id", "parent_id" = excluded."parent_id", "author_id" = excluded."author_id", "anon_id" = excluded."anon_id", "content" = excluded."content", "created_at" = excluded."created_at";
INSERT INTO "comments" ("id", "issue_id", "parent_id", "author_id", "anon_id", "content", "created_at") VALUES ('c0000000-0000-4000-8000-000000000014', 8, NULL, 5, 'anon_2d46379e858dd668', 'School bus drivers are avoiding this stretch because of the rubble.', '2026-08-09 09:00:00.000000') ON CONFLICT ("id") DO UPDATE SET "issue_id" = excluded."issue_id", "parent_id" = excluded."parent_id", "author_id" = excluded."author_id", "anon_id" = excluded."anon_id", "content" = excluded."content", "created_at" = excluded."created_at";
