INSERT INTO "official_responses" ("id", "issue_id", "representative_id", "message", "estimated_resolution_days", "status_update", "created_at") VALUES ('off_resp_seed_8', 8, 'rep_ward45_urban_central', 'Road repair work in front of Z.P. School has been scheduled under the ward resurfacing drive. Work will begin after the rains ease.', 10, 'acknowledged', '2026-08-09 15:00:00.000000') ON CONFLICT ("id") DO UPDATE SET "issue_id" = excluded."issue_id", "representative_id" = excluded."representative_id", "message" = excluded."message", "estimated_resolution_days" = excluded."estimated_resolution_days", "status_update" = excluded."status_update", "created_at" = excluded."created_at";
